import json

# Rules inferred from the data:
#  - initial *d -> t, *b -> p (voiced stops devoice)
#  - presyllable *ə -> a (cf. *bəsey -> pathey)
#  - a voiced stop (b, d, j, g) in the proto form puts a grave accent
#    on the main-syllable vowel (cf. *padam -> patàm, *bara -> pirà,
#    *bubah -> papàh), while forms without one do not (cf. *paley -> paley)

proto = "dəpa"
grave = {"a": "à", "i": "ì", "u": "ù", "o": "ò", "e": "è"}

def derive(p):
    voiced = any(c in "bdjg" for c in p)
    out = []
    for i, c in enumerate(p):
        if c == "d":
            out.append("t")
        elif c == "b":
            out.append("p")
        elif c == "ə" and i < len(p) - 2:
            out.append("a")
        else:
            out.append(c)
    s = "".join(out)
    if voiced:
        # accent the last vowel of the main syllable
        for i in range(len(s) - 1, -1, -1):
            if s[i] in grave:
                s = s[:i] + grave[s[i]] + s[i + 1:]
                break
    return s

ans = derive(proto)
print(json.dumps({
    "final_answer": ans,
    "evidence": {
        "proto": "*" + proto,
        "rules": "d->t; presyllable ə->a; voiced stop in proto -> grave on final vowel",
        "analogues": ["*dilah>talàh", "*padam>patàm", "*bəsey>pathey", "*bara>pirà"]
    }
}, ensure_ascii=False))
